query.gsql:
INTERPRET QUERY () FOR GRAPH shop {
  Start = {Person.*};
  Result = SELECT s FROM Start:s LIMIT 100;
  PRINT Result;
}

INTERPRET QUERY () FOR GRAPH shop {
  Start = {Person.*};
  Result = SELECT t FROM Start:s -(KNOWS:e)- :t LIMIT 100;
  PRINT Result;
}

INTERPRET QUERY () FOR GRAPH shop {
  SumAccum<INT> @@n;
  Start = {Person.*};
  Result = SELECT s FROM Start:s ACCUM @@n += 1;
  PRINT @@n;
}

INTERPRET QUERY () FOR GRAPH shop {
  Start = {Person.*};
  Result = SELECT s FROM Start:s WHERE s.name == "value" LIMIT 100;
  PRINT Result;
}

INTERPRET QUERY () FOR GRAPH shop {
  Start = {Person.*};
  Result = SELECT s FROM Start:s ORDER BY s.name DESC LIMIT 10;
  PRINT Result;
}

INTERPRET QUERY () FOR GRAPH shop {
  SumAccum<INT> @degree;
  Start = {Person.*};
  Result = SELECT s FROM Start:s -(KNOWS:e)- :t ACCUM s.@degree += 1 ORDER BY s.@degree DESC LIMIT 10;
  PRINT Result;
}

INTERPRET QUERY () FOR GRAPH shop {
  Start = {Person.*};
  Result = SELECT s FROM Start:s LIMIT 5;
  PRINT Result;
}

